package android.view; public class MotionEvent { public static final int ACTION_DOWN=0,ACTION_UP=1,ACTION_MOVE=2,ACTION_CANCEL=3,ACTION_OUTSIDE=4; int action;float x,y; public MotionEvent(int a,float x,float y){action=a;this.x=x;this.y=y;} public int getActionMasked(){return action;} public float getRawX(){return x;} public float getRawY(){return y;} public float getX(){return x;} public float getY(){return y;} public int getPointerCount(){return 1;} public static MotionEvent obtain(MotionEvent e){return new MotionEvent(e.action,e.x,e.y);} public void setAction(int a){action=a;} public void recycle(){} }